namespace {
std::string context;
void check(bool ok,const std::string& why){if(!ok)throw std::runtime_error(context+": "+why);}
std::vector<Pixel> words(const JsonArray& a){std::vector<Pixel> result;for(auto v:a)result.push_back(Pixel(v.GetNumber()));return result;}
void equalPixels(const std::vector<Pixel>& actual,const JsonArray& expected,const std::string& why){const auto wanted=words(expected);if(actual==wanted)return;for(std::size_t i=0;i<std::min(actual.size(),wanted.size());++i)if(actual[i]!=wanted[i])check(false,why+" pixel "+std::to_string(i)+" got "+std::to_string(actual[i])+" wanted "+std::to_string(wanted[i]));check(false,why+" length");}
void encoded(const Document& d){if(d.colorMode()!=color_mode::Mode::Indexed)return;bool duplicates=false;std::unordered_set<int> ids;for(const auto& e:d.palette().entries)duplicates|=!ids.insert(e.id).second;
 for(int k=0;k<3;++k){try{auto out=k==0?project::encodeEditableProject(d):k==1?project::encodeRecoveryProject(d):project::encodeHistoryProject(d);check(!duplicates,"encoder accepted duplicates");auto manifest=project::readProjectManifest(out.bytes);project::Archive zip(out.bytes);check(manifest.colorMode=="indexed","encoded mode");for(const auto& c:manifest.cels)if(c.surface){const auto* runtime=d.timeline().resolveSurface(c.id).surface;const auto& s=*c.surface;check(runtime&&s.format==project::RasterFormat::Indexed&&project::decodeRaster(zip.read(s.dataFile,project::Limits{}.expandedBytes),s.dataEncoding,s.format,s.width,s.height,project::Limits{}.expandedBytes)==runtime->pixels,"encoded raw IDs");}bool gated=false;try{project::prepareEditableImport(manifest);}catch(const project::Error& e){gated=e.kind==project::ErrorKind::Unsupported;}check(gated,"indexed production admission");}catch(const project::Error& e){check(duplicates&&e.kind==project::ErrorKind::Corrupt,std::string("encoder error: ")+e.what());}}
}
}
namespace {
std::optional<timeline::ColorOverlayStyle> style(int effect){if(!effect)return {};timeline::ColorOverlayStyle s;if(effect==1){s.stroke.enabled=true;s.stroke.color=0xff0000ff;}if(effect==2){s.shadow.enabled=true;s.shadow.color=0xff0000ff;s.shadow.offsetX=1;s.shadow.offsetY=0;}if(effect==3){s.gradientEnabled=true;s.gradientFrom=0xffff0000;s.gradientTo=0xff0000ff;}return s;}
WandOptions options(const JsonObject& row){WandOptions o;o.tolerance=int(row.GetNamedNumber(L"tolerance"));o.connectivity=int(row.GetNamedNumber(L"connectivity"));o.contiguous=row.GetNamedBoolean(L"contiguous");o.gapThreshold=int(row.GetNamedNumber(L"gap"));o.gapClosing=o.gapThreshold>0;o.visibleLayers=row.GetNamedBoolean(L"visible");return o;}
Point seed(const JsonObject& row){const auto p=row.GetNamedArray(L"seed");return {int(p.GetNumberAt(0)),int(p.GetNumberAt(1))};}
}
namespace moon {struct RasterHistoryFixture {
 static std::unique_ptr<Document> make(const JsonObject& row,bool linked){
  auto d=std::make_unique<Document>(int(row.GetNamedNumber(L"w")),int(row.GetNamedNumber(L"h")));auto state=d->timeline_.state();auto& s=*state.cels.front().surface;
  s.format=row.GetNamedString(L"format")==L"indexed"?timeline::RasterFormat::Indexed:timeline::RasterFormat::Rgba;s.width=int(row.GetNamedNumber(L"sw"));s.height=int(row.GetNamedNumber(L"sh"));s.offsetX=int(row.GetNamedNumber(L"ox"));s.offsetY=int(row.GetNamedNumber(L"oy"));s.storageOriginX=5;s.storageOriginY=-3;s.pixels=words(row.GetNamedArray(L"initial"));
  state.layers.front().layerStyles=style(int(row.GetNamedNumber(L"effect")));
  if(row.GetNamedBoolean(L"visible")){auto layer=state.layers.front();layer.id="top-visible";layer.layerStyles.reset();state.layers.push_back(layer);auto top=state.cels.front();top.id="top-visible-cel";top.layerId=layer.id;top.surface=timeline::Surface{};top.surface->width=d->width();top.surface->height=d->height();top.surface->format=row.GetNamedString(L"format")==L"indexed"?timeline::RasterFormat::Indexed:timeline::RasterFormat::Rgba;top.surface->pixels=words(row.GetNamedArray(L"peer"));state.cels.push_back(std::move(top));}
  if(linked){auto layer=state.layers.front();layer.id="peer";layer.visible=false;layer.linkedContentId="magic-erase-fixture";state.layers.front().linkedContentId=layer.linkedContentId;state.layers.push_back(layer);auto cel=state.cels.front();cel.id="peer-cel";cel.layerId=layer.id;state.cels.push_back(cel);state.frames.push_back({"alias-frame",100});for(unsigned i=0;i<2;++i){timeline::Cel alias;alias.id="alias-"+std::to_string(i);alias.layerId=i?"peer":state.layers.front().id;alias.frameId="alias-frame";alias.linkedCelId=i?"peer-cel":state.cels.front().id;state.cels.push_back(alias);}}
  d->timeline_=timeline::Timeline(std::move(state));d->colorMode_=row.GetNamedString(L"format")==L"indexed"?color_mode::Mode::Indexed:color_mode::Mode::Rgba;d->palette_.entries.clear();d->palette_.slots.clear();
  for(auto v:row.GetNamedArray(L"entries")){auto e=v.GetObject();d->palette_.entries.push_back({int(e.GetNamedNumber(L"id")),U"color",Pixel(e.GetNamedNumber(L"color"))});}
  std::vector<int> order;for(auto x:words(row.GetNamedArray(L"order")))order.push_back(int(x));d->palette_.setOrder(std::move(order));d->palette_.nextId=100;d->projectActiveCelOpacities();
  if(row.GetNamedValue(L"selection").ValueType()==JsonValueType::Object){auto v=row.GetNamedObject(L"selection");SelectionMask selection{int(v.GetNamedNumber(L"x")),int(v.GetNamedNumber(L"y")),int(v.GetNamedNumber(L"width")),int(v.GetNamedNumber(L"height")),{}};if(v.HasKey(L"mask"))for(auto x:words(v.GetNamedArray(L"mask")))selection.mask.push_back(std::uint8_t(x));d->previewSelection(selection);}
  d->markSaved();return d;
 }
 static void verify(const Document& d,const JsonObject& row,const wchar_t* field,const wchar_t* storage,bool linked){equalPixels(d.canvasPixels(),row.GetNamedArray(field),winrt::to_string(field));const auto& s=*d.activeSurfaceIfPresent();equalPixels(s.pixels,row.GetNamedArray(storage),winrt::to_string(storage));check(s.width==int(row.GetNamedNumber(L"sw"))&&s.height==int(row.GetNamedNumber(L"sh"))&&s.offsetX==int(row.GetNamedNumber(L"ox"))&&s.offsetY==int(row.GetNamedNumber(L"oy"))&&s.storageOriginX==5&&s.storageOriginY==-3,"geometry changed");check(s.format==(row.GetNamedString(L"format")==L"indexed"?timeline::RasterFormat::Indexed:timeline::RasterFormat::Rgba),"format");if(linked)for(const auto& c:d.timeline_.state().cels)if(c.layerId!="top-visible"){const auto r=d.timeline_.resolveSurface(c.id);check(r.surface&&r.surface->pixels.identity()==s.pixels.identity(),"shared owner");}if(row.GetNamedBoolean(L"visible")){const auto* peer=d.timeline_.findCel("top-visible",d.frame().id);check(peer&&peer->surface,"sample peer missing");equalPixels(peer->surface->pixels,row.GetNamedArray(L"peer"),"sampled layer changed");}}
 static void run(const JsonObject& row,bool linked=false){auto d=make(row,linked);const auto selection=d->selection();const auto pal=d->palette_;const bool changed=row.GetNamedBoolean(L"changed");const auto p=seed(row);const auto o=options(row);
  check(d->eraseMatchingColor(p,o,true)==changed,"preview presence");verify(*d,row,L"after",L"afterStorage",linked);check(!d->historySize()&&d->dirty()==changed&&d->active()==changed,"preview state");d->cancelStroke();verify(*d,row,L"cancel",L"cancelStorage",linked);check(!d->historySize()&&!d->dirty()&&!d->active(),"cancel state");
  d=make(row,linked);const auto active=d->cel().id;check(d->eraseMatchingColor(p,o)==changed,"direct result");verify(*d,row,L"after",L"afterStorage",linked);check(d->historySize()==(changed?1:0)&&d->dirty()==changed&&!d->active(),"single history/no-op");check(indexed_adjustment::samePaletteData(pal,d->palette_)&&selectionEqual(selection,d->selection())&&d->cel().id==active,"palette/selection/active");
  if(changed){check(d->history_.latest().label==U"\u9b54\u672f\u6a61\u76ae\u64e6","history label");check(bool(d->history_.latest().contentHistory.dense)==row.GetNamedBoolean(L"dense"),"dense threshold");if(row.GetNamedValue(L"replayOrder").ValueType()==JsonValueType::Array){std::vector<int> order;for(auto id:words(row.GetNamedArray(L"replayOrder")))order.push_back(int(id));d->palette_.setOrder(std::move(order));}const auto current=d->palette_;if(linked)encoded(*d);d->undo();verify(*d,row,L"undo",L"undoStorage",linked);check(indexed_adjustment::samePaletteData(current,d->palette_),"undo palette");if(linked)encoded(*d);d->redo();verify(*d,row,L"redo",L"redoStorage",linked);if(linked)encoded(*d);
   d=make(row,linked);check(d->eraseMatchingColor(p,o,true),"preview before commit");{Document::HistoryLabelScope label(*d,U"\u9b54\u672f\u6a61\u76ae\u64e6");check(d->commitStroke(),"preview commit");}check(d->historySize()==1&&d->history_.latest().label==U"\u9b54\u672f\u6a61\u76ae\u64e6","preview single history/label");verify(*d,row,L"after",L"afterStorage",linked);
  }
 }
 static void mask(const JsonObject& row){
  auto makeMask=[&]{auto d=std::make_unique<Document>(int(row.GetNamedNumber(L"w")),int(row.GetNamedNumber(L"h")));auto t=d->timeline_.state();t.cels.front().surface->format=row.GetNamedString(L"format")==L"indexed"?timeline::RasterFormat::Indexed:timeline::RasterFormat::Rgba;timeline::MaskSlot slot;slot.ownerId=t.layers.front().id;slot.frameId=t.frames.front().id;slot.mask.id="magic-mask";auto& s=slot.mask.surface;s.width=int(row.GetNamedNumber(L"sw"));s.height=int(row.GetNamedNumber(L"sh"));s.offsetX=int(row.GetNamedNumber(L"ox"));s.offsetY=int(row.GetNamedNumber(L"oy"));s.storageOriginX=5;s.storageOriginY=-3;s.pixels=words(row.GetNamedArray(L"initial"));t.masks.push_back(std::move(slot));d->timeline_=timeline::Timeline(std::move(t));d->colorMode_=row.GetNamedString(L"format")==L"indexed"?color_mode::Mode::Indexed:color_mode::Mode::Rgba;check(d->selectAttachedMask(d->layer().id,d->frame().id),"select mask");if(row.GetNamedValue(L"selection").ValueType()==JsonValueType::Object){const auto v=row.GetNamedObject(L"selection");SelectionMask selection{int(v.GetNamedNumber(L"x")),int(v.GetNamedNumber(L"y")),int(v.GetNamedNumber(L"width")),int(v.GetNamedNumber(L"height")),{}};for(auto x:words(v.GetNamedArray(L"mask")))selection.mask.push_back(std::uint8_t(x));d->previewSelection(selection);}d->markSaved();return d;};
  auto d=makeMask();const auto base=d->canvasPixels();const auto palette=d->palette_;const auto selection=d->selection();const auto original=d->activeMask()->surface;const bool changed=row.GetNamedBoolean(L"changed");
  auto verify=[&](const wchar_t* field){const auto* m=d->activeMask();check(m&&m->surface.width==original.width&&m->surface.height==original.height&&m->surface.offsetX==original.offsetX&&m->surface.offsetY==original.offsetY&&m->surface.storageOriginX==5&&m->surface.storageOriginY==-3,"mask geometry");equalPixels(m->surface.pixels,row.GetNamedArray(field),winrt::to_string(field));check(d->canvasPixels()==base&&indexed_adjustment::samePaletteData(d->palette_,palette)&&selectionEqual(d->selection(),selection),"mask changed raster/palette/selection");};
  check(d->eraseMatchingColor(seed(row),options(row),true)==changed,"mask preview result");verify(L"after");d->cancelStroke();verify(L"cancel");check(!d->dirty()&&!d->historySize(),"mask cancel history");d=makeMask();check(d->eraseMatchingColor(seed(row),options(row))==changed,"mask commit");verify(L"after");if(changed){check(d->historySize()==1,"mask single history");d->undo();verify(L"undo");d->redo();verify(L"redo");}
 }
 static void unavailable(const JsonObject& row){for(int kind=0;kind<6;++kind){auto d=make(row,false);auto t=d->timeline_.state();if(kind==0)t.layers.front().locked=true;if(kind==1)t.layers.front().visible=false;if(kind==2)t.layers.front().kind="text";if(kind==3)t.cels.erase(t.cels.begin());if(kind<4)d->timeline_=timeline::Timeline(std::move(t));if(kind==4)d->previewSelection(SelectionMask{0,0,1,1,{}});if(kind==5)d->beginStroke({1,1},0xffabcdef,{},nullptr,0,nullptr,false);const auto count=d->timeline_.state().cels.size(),revision=d->revision(),history=d->historySize();check(!d->eraseMatchingColor({3,3},options(row),true),"unavailable preview");check(!d->eraseMatchingColor({-1,0},options(row),true),"outside preview");check(d->timeline_.state().cels.size()==count&&d->revision()==revision&&d->historySize()==history,"unavailable changed state");d->cancelStroke();}}
};}
int run(int argc,wchar_t** argv){check(argc==2,"oracle path");std::ifstream in(std::filesystem::path(argv[1]),std::ios::binary);check(bool(in),"missing oracle");const std::string bytes{std::istreambuf_iterator<char>(in),{}};const auto data=JsonObject::Parse(winrt::to_hstring(bytes));const auto rows=data.GetNamedArray(L"cases");check(rows.Size()==2492,"oracle coverage");unsigned links=0,dense=0;for(unsigned i=0;i<rows.Size();++i){const auto row=rows.GetObjectAt(i);context=winrt::to_string(row.GetNamedString(L"name"));RasterHistoryFixture::run(row);if(row.GetNamedBoolean(L"dense"))++dense;if(i%29==0||row.GetNamedBoolean(L"dense")){RasterHistoryFixture::run(row,true);++links;}}const auto masks=data.GetNamedArray(L"masks");check(masks.Size()==48,"mask coverage");for(auto v:masks){auto row=v.GetObject();context=winrt::to_string(row.GetNamedString(L"name"));RasterHistoryFixture::mask(row);}context="unavailable";RasterHistoryFixture::unavailable(rows.GetObjectAt(0));std::cout<<rows.Size()<<" actual legacy magic erase cases, "<<dense<<" dense histories and "<<links<<" linked/codec variants and 48 mask transactions passed\n";return 0;}
int wmain(int argc,wchar_t** argv){const auto hr=RoInitialize(RO_INIT_MULTITHREADED);try{const auto result=run(argc,argv);if(hr==S_OK)winrt::clear_factory_cache();if(SUCCEEDED(hr))RoUninitialize();return result;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';if(hr==S_OK)winrt::clear_factory_cache();if(SUCCEEDED(hr))RoUninitialize();return 1;}}
